#!/usr/bin/env node
// Pulls the marketing screenshots generated by wavekat-voice's screenshot
// pipeline (its docs/41 — `make screenshots`) into src/assets/screenshots/,
// so the site can show the real app, localized, in light and dark.
//
// Why this is a *commit* step, not a build step
// ---------------------------------------------
// The screenshots are git-ignored build artifacts in wavekat-voice (they're
// never committed there, and aren't in any release tag), and the site builds
// on Cloudflare Pages where the private renderer isn't available. So unlike
// `sync-docs.js` (which clones at build time), the chosen screenshots are
// *committed* into this repo — they are the source of truth for the build, and
// Astro's <Image> re-encodes them to WebP/AVIF at delivery. This script just
// refreshes those committed PNGs from a local wavekat-voice checkout when the
// app UI changes.
//
// Source (first that exists):
//   WAVEKAT_SCREENSHOTS_DIR=<dir>          — a screenshots/ dir directly
//   WAVEKAT_LOCAL_REPOS=<base>             — <base>/wavekat-voice/apps/desktop/screenshots
//   ../wavekat-voice/apps/desktop/screenshots   (default sibling checkout)
//
// To regenerate the source first, in the wavekat-voice repo:
//   make screenshots          # capture the full matrix (bare content)
// then here:
//   npm run sync:screenshots  # copy + optimize the curated subset
//
// Usage:
//   node scripts/sync-screenshots.js          # refresh committed PNGs
//   node scripts/sync-screenshots.js --check  # verify all are present, no write

import { existsSync, mkdirSync, rmSync, readdirSync, statSync } from "fs";
import { join } from "path";
import { fileURLToPath } from "url";
import sharp from "sharp";

const root = join(fileURLToPath(import.meta.url), "../..");
const destRoot = join(root, "src/assets/screenshots");

// The scenes we actually surface on the site. Keep this in sync with the
// <AppScreenshot scene="…"> usages; only these are committed (not the full
// matrix wavekat-voice produces) to keep the repo light.
const SCENES = [
  "home",
  "incoming-call",
  "in-call",
  "history",
  "call-details",
  "add-account",
];

// The nine shipped interface languages, by wavekat.com locale `code` — which
// is exactly the filename wavekat-voice writes (`<code>-<theme>.png`).
const CODES = [
  "en",
  "zh-Hans",
  "zh-Hant",
  "ja",
  "ko",
  "de",
  "es",
  "fr",
  "it",
];
const THEMES = ["light", "dark"];

// Captured at 960×640@2× (1920 wide). The site never shows them wider than the
// ~720px content column, so 1366 (a crisp ~2×) is plenty. Committed as WebP
// q88 — visually lossless for flat UI, ~35 KB each (vs ~150 KB PNG), so the
// whole set is a few MB, not ~18. Astro re-encodes responsive WebP/AVIF from
// this source at delivery.
const MAX_WIDTH = 1366;
const WEBP_QUALITY = 88;
const EXT = "webp";

function resolveSourceDir() {
  const direct = process.env.WAVEKAT_SCREENSHOTS_DIR;
  if (direct) return direct;
  const base = process.env.WAVEKAT_LOCAL_REPOS;
  if (base) return join(base, "wavekat-voice/apps/desktop/screenshots");
  return join(root, "../wavekat-voice/apps/desktop/screenshots");
}

const check = process.argv.includes("--check");

function expectedFiles() {
  const out = [];
  for (const scene of SCENES) {
    for (const code of CODES) {
      for (const theme of THEMES) {
        out.push({ scene, name: `${code}-${theme}.${EXT}` });
      }
    }
  }
  return out;
}

if (check) {
  const missing = expectedFiles().filter(
    ({ scene, name }) => !existsSync(join(destRoot, scene, name)),
  );
  if (missing.length) {
    console.error(
      `✗ ${missing.length} committed screenshot(s) missing:\n` +
        missing.map((m) => `   ${m.scene}/${m.name}`).join("\n") +
        `\n\nRegenerate with \`make screenshots\` in wavekat-voice, then ` +
        `\`npm run sync:screenshots\` here.`,
    );
    process.exit(1);
  }
  console.log(`✓ all ${expectedFiles().length} screenshots present`);
  process.exit(0);
}

const srcRoot = resolveSourceDir();
if (!existsSync(srcRoot)) {
  console.error(
    `✗ no screenshots at ${srcRoot}\n\n` +
      `Generate them first — in your wavekat-voice checkout:\n` +
      `   make screenshots\n\n` +
      `then point this script at them with WAVEKAT_SCREENSHOTS_DIR=<dir>, ` +
      `WAVEKAT_LOCAL_REPOS=<base>, or a sibling ../wavekat-voice checkout.`,
  );
  process.exit(1);
}

console.log(`▶ syncing screenshots from ${srcRoot}`);
rmSync(destRoot, { recursive: true, force: true });

let written = 0;
const missing = [];
for (const scene of SCENES) {
  const srcDir = join(srcRoot, scene);
  if (!existsSync(srcDir)) {
    missing.push(`${scene}/ (whole scene)`);
    continue;
  }
  const destDir = join(destRoot, scene);
  mkdirSync(destDir, { recursive: true });
  for (const code of CODES) {
    for (const theme of THEMES) {
      const src = join(srcDir, `${code}-${theme}.png`);
      const name = `${code}-${theme}.${EXT}`;
      if (!existsSync(src)) {
        missing.push(`${scene}/${code}-${theme}.png`);
        continue;
      }
      await sharp(src)
        .resize({ width: MAX_WIDTH, withoutEnlargement: true })
        .webp({ quality: WEBP_QUALITY, effort: 6 })
        .toFile(join(destDir, name));
      written++;
    }
  }
}

console.log(`✓ wrote ${written} screenshots → src/assets/screenshots/`);
if (missing.length) {
  console.warn(
    `\n⚠ ${missing.length} expected file(s) not found in source ` +
      `(did the matrix finish?):\n` +
      missing.map((m) => `   ${m}`).join("\n"),
  );
  process.exitCode = 1;
}

// A quick weight report so a careless re-encode that bloats the repo is
// obvious in the command output.
const totalKb = SCENES.reduce((sum, scene) => {
  const d = join(destRoot, scene);
  if (!existsSync(d)) return sum;
  for (const f of readdirSync(d)) {
    sum += Math.round(statSync(join(d, f)).size / 1024);
  }
  return sum;
}, 0);
console.log(`  (~${(totalKb / 1024).toFixed(1)} MB committed)`);
